  // Mobile L1/L2 drawer state (SFCC-97). Base `_app`'s `useDisclosure` passes `onMenuClick`
  // (its `onOpen`) to Header directly, but `isOpen`/`onClose` go straight to the sibling
  // `<DrawerMenu>` it renders as Header's own `children` — Header has no `onClose` prop of
  // its own. `useHeaderMenuExpandedState` owns the depth (closed/L1/L2) state this shell needs
  // for LeftBar/RightBar's `menuExpanded`, and `DrawerMenuStateContext` (provided around
  // `children` below) is how the nested DrawerMenu and this shell share it without Header
  // needing to know `_app.jsx`'s exact children shape — see both hooks' own JSDoc.
  const {
    menuExpanded: mobileMenuExpanded,
    handleMenuClick,
    handleBack,
    handleClose,
    contextValue,
  } = useHeaderMenuExpandedState(onMenuClick);

  // Combined menuExpanded for LeftBar/RightBar (see headerTypes.ts): the desktop/tablet
  // mega-menu ('fullSwap') and the mobile drawer ('mobileL1'/'mobileL2') are mutually
  // exclusive by breakpoint in practice (LeftBar/RightBar's own recipes hide one control set
  // per breakpoint), but both pieces of state genuinely coexist in this shell — SFCC-96 owns
  // `isMegaMenuOpen`, SFCC-97 owns `mobileMenuExpanded`. Mobile state takes precedence when
  // active; otherwise fall through to the desktop mega-menu state. `onCloseMenu` below picks
  // the matching close handler the same way, so RightBar's single `onClose` prop always closes
  // whichever one is actually open.
  const menuExpanded: MenuExpandedState =
    mobileMenuExpanded !== 'closed' ? mobileMenuExpanded : isMegaMenuOpen ? 'fullSwap' : 'closed';
  const onCloseMenu = mobileMenuExpanded !== 'closed' ? handleClose : closeMegaMenu;

  // Filter navigation links based on 1CC configuration
  const filteredNavLinks = isOneClickCheckoutEnabled
    ? (navLinks as NavLink[])
    : (navLinks as NavLink[]).filter((link) => link.name !== 'payments');

  const onSignout = async () => {
    if (showLoading) return;
    setShowLoading(true);
    try {
      await logout.mutateAsync();
      navigate('/login');
    } finally {
      setShowLoading(false);
    }
  };

  const styles = useMultiStyleConfig('Header');

  return (
    <MegaMenuOpenContext.Provider value={megaMenuOpenReporter}>
      <chakra.header __css={styles.container} role="banner" {...props}>
        <chakra.div __css={HEADER_CONTENT_SX}>
          {showLoading && <LoadingSpinner wrapperStyles={{ height: '100vh' }} />}

          {/* ── Row 1: top bar ─────────────────────────────────────────────── */}
          <chakra.div __css={styles.topBar}>
            <LeftBar onMenuClick={handleMenuClick} menuExpanded={menuExpanded} onBack={handleBack}>
              <DrawerMenuStateContext.Provider value={contextValue}>{children}</DrawerMenuStateContext.Provider>
            </LeftBar>
            <RightBar
              hasBasket={!!basket}
              totalItems={totalItems}
              isRegistered={isRegistered}
              filteredNavLinks={filteredNavLinks}
              showLaunchAgentButton={showLaunchAgentButton}
              storeLocatorEnabled={storeLocatorEnabled}
              searchInputRef={searchInputRef}
              onMyAccountClick={onMyAccountClick}
              onMyCartClick={onMyCartClick}
              onWishlistClick={onWishlistClick}
              onAgentClick={onAgentClick}
              onStoreLocatorClick={onStoreLocatorClick}
              onSignout={onSignout}
              menuExpanded={menuExpanded}
              onClose={onCloseMenu}
            />
          </chakra.div>

          {/* ── Row 2: logo only — hidden while the mobile drawer is open. Figma's mobile
              "Navigation" component drops to a 72px Exit/search/bag row with no wordmark. */}
          {/* display:flex lives in header.ts's logoBar recipe — no inline prop needed. */}
          {mobileMenuExpanded === 'closed' && (
            <chakra.div __css={styles.logoBar}>
              <Button
                aria-label={t('header.button.assistive_msg.logo', 'Logo')}
                variant="unstyled"
                onClick={onLogoClick}
                __css={styles.logoButton}
              >
                {/* SFCC-747: real wordmark, sized via HEADER_LOGO_SX above — previously rendered
                    the base template's placeholder BrandLogo icon. `sx`, not `style`: a plain
                    DOM style attribute can't express Chakra's responsive breakpoint values. */}
                <ZimmLogo sx={HEADER_LOGO_SX} />
              </Button>
            </chakra.div>
          )}

          {/* Mobile-only search — commented out, pending searchPopover implementation */}
          {/* <HideOnDesktop display={{ base: 'block', lg: 'none' }}><SearchBar /></HideOnDesktop> */}
        </chakra.div>
      </chakra.header>
    </MegaMenuOpenContext.Provider>
  );
};

export default Header;

