1	import React, { useRef, useState } from 'react';
2	import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
3	import {
4	  IconButton,
5	  Badge,
6	  Button,
7	  Popover,
8	  PopoverHeader,
9	  PopoverTrigger,
10	  PopoverContent,
11	  PopoverBody,
12	  PopoverFooter,
13	  PopoverArrow,
14	  Text,
15	  Divider,
16	  useDisclosure,
17	} from '@salesforce/retail-react-app/app/components/shared/ui';
18	import withRegistration from '@salesforce/retail-react-app/app/components/with-registration';
19	import Link from '@salesforce/retail-react-app/app/components/link';
20	import { isHydrated, noop } from '@salesforce/retail-react-app/app/utils/utils';
21	import { SignoutIcon, SparkleIcon } from 'app/components/icons';
22	import { ZimmIcon } from 'app/components/ui-kits/atoms/zimmIcon';
23	import { ZimmSearchInput } from 'app/components/ui-kits/atoms/zimmSearchInput';
24	import { useUiCopy } from 'app/hooks/useUiCopy';
25	import type { MenuExpandedState } from '../headerTypes';
26	
27	// `withRegistration` wraps a button so it redirects to login when the user is not
28	// registered. Kept local to RightBar — only the right section uses it.
29	const IconButtonWithRegistration = withRegistration(IconButton);
30	
31	type NavLink = {
32	  name: string;
33	  path: string;
34	  icon: React.ComponentType<{ boxSize: number }>;
35	};
36	
37	// The account popover's nav-link labels used to come from base SFCC's own `messages` map
38	// (@salesforce/retail-react-app/app/pages/account/constant), read via
39	// `intl.formatMessage(messages[link.name])`. That's vendor react-intl content we don't own,
40	// with no local uiCopy equivalent — replaced with our own key/fallback pair per `link.name`,
41	// fallback text matching the vendor map's own defaultMessage so behaviour is unchanged until
42	// someone edits these in Contentful. `filteredNavLinks` is always sourced from that same
43	// vendor `navLinks` list (see header/index.tsx), so every real `name` it can contain has an
44	// entry here — `link.name` itself is the fallback for a name this map doesn't recognise.
45	const ACCOUNT_NAV_LABELS: Record<string, { key: string; fallback: string }> = {
46	  profile: { key: 'header.popover.nav.profile', fallback: 'Account Details' },
47	  addresses: { key: 'header.popover.nav.addresses', fallback: 'Addresses' },
48	  orders: { key: 'header.popover.nav.orders', fallback: 'Order History' },
49	  wishlist: { key: 'header.popover.nav.wishlist', fallback: 'Wishlist' },
50	  payments: { key: 'header.popover.nav.payments', fallback: 'Payment Methods' },
51	};
52	
53	type RightBarProps = {
54	  /** True when an active basket exists — controls bag badge visibility. */
55	  hasBasket: boolean;
56	  /** Total item count shown on the bag icon badge. */
57	  totalItems: number;
58	  /** Whether the shopper is a registered (logged-in) customer. */
59	  isRegistered: boolean;
60	  /** Account nav links, pre-filtered by the shell based on 1CC configuration. */
61	  filteredNavLinks: ReadonlyArray<NavLink>;
62	  /** Whether the commerce agent button should be shown (config-driven). */
63	  showLaunchAgentButton: boolean;
64	  /** Whether the store locator mobile icon should be shown (config-driven). */
65	  storeLocatorEnabled: boolean;
66	  /** Forwarded to ZimmSearchInput for programmatic search focus. */
67	  searchInputRef?: React.Ref<HTMLInputElement>;
68	  onMyAccountClick?: () => void;
69	  onMyCartClick?: () => void;
70	  onWishlistClick?: () => void;
71	  onAgentClick?: () => void;
72	  onStoreLocatorClick?: () => void;
73	  /** Async logout + navigate handler owned by the header shell container. */
74	  onSignout: () => Promise<void>;
75	  /** Current menu-expansion state — see header/headerTypes.ts. Defaults to 'closed'.
76	   * 'fullSwap' (desktop/tablet) replaces the entire search+icon cluster with a single
77	   * Close control; 'mobileL2' adds a close icon alongside the mobile search+bag icons.
78	   * 'mobileL1' has no effect here — that toggle lives entirely in LeftBar's hamburger⇄X.
79	   * Not wired to any real mega-menu/drawer state on this branch — see headerTypes.ts's
80	   * scope note (SFCC-96/97 follow-up). */
81	  menuExpanded?: MenuExpandedState;
82	  /** Close-control click handler — fires from the desktop/tablet 'fullSwap' control and
83	   * the mobile 'mobileL2' close icon. Not yet wired to anything real on this branch. */
84	  onClose?: () => void;
85	};
86	
87	/**
88	 * Header right section — desktop: search input + Profile / Wishlist / Bag icon buttons;
89	 * tablet: search icon + Profile / Wishlist / Bag icon buttons;
90	 * mobile: search icon + bag icon only (Figma node 40000307:11868).
91	 *
92	 * `menuExpanded` (see header/headerTypes.ts) swaps this section's contents:
93	 *   - 'closed'/'mobileL1' → unchanged, as above
94	 *   - 'fullSwap' (desktop/tablet) → the entire search+icon cluster is replaced by a
95	 *     single "Close" text + X control
96	 *   - 'mobileL2' → the mobile search + bag icons stay, plus an added close X icon
97	 *
98	 * Owns account-popover UI state (useDisclosure, focus refs) internally. Commerce data and
99	 * auth side-effects are passed as props from the header shell container so this component
100	 * stays presentational relative to the Commerce Cloud API.
101	 *
102	 * Single-parent internal component (only the header shell renders it); story coverage is
103	 * via the header's own assembly story.
104	 *
105	 * @param props see RightBarProps
106	 */
107	export const RightBar = ({
108	  hasBasket,
109	  totalItems,
110	  isRegistered,
111	  filteredNavLinks,
112	  showLaunchAgentButton,
113	  storeLocatorEnabled,
114	  searchInputRef,
115	  onMyAccountClick = noop,
116	  onMyCartClick = noop,
117	  onWishlistClick = noop,
118	  onAgentClick = noop,
119	  onStoreLocatorClick = noop,
120	  onSignout,
121	  menuExpanded = 'closed',
122	  onClose = noop,
123	}: RightBarProps) => {
124	  const { t } = useUiCopy();
125	  // Own recipe handles searchWrapper and iconGroup styles.
126	  const styles = useMultiStyleConfig('ZimmHeaderRightBar');
127	  // Header theme styles shared with this section: icons, agentIcon, signout*, popoverContent.
128	  // Referencing the parent Header theme is intentional — these styles live in the SFCC base
129	  // theme and our header.ts override; duplicating them into ZimmHeaderRightBar would drift.
130	  const headerStyles = useMultiStyleConfig('Header');
131	
132	  // Account popover UI state — owned here so the header shell stays free of popover refs.
133	  const popoverTriggerRef = useRef<HTMLButtonElement>(null);
134	  const hasEnterPopoverContent = useRef<boolean>();
135	  const [isSigningOut, setIsSigningOut] = useState(false);
136	
137	  const {
138	    getButtonProps: getAccountMenuButtonProps,
139	    getDisclosureProps: getAccountMenuDisclosureProps,
140	    isOpen: isAccountMenuOpen,
141	    onClose: onAccountMenuClose,
142	    onOpen: onAccountMenuOpen,
143	  } = useDisclosure();
144	
145	  const handleIconsMouseLeave = () => {
146	    // Close menu only if the pointer hasn't moved into the popover content.
147	    setTimeout(() => {
148	      if (!hasEnterPopoverContent.current) onAccountMenuClose();
149	    }, 100);
150	  };
151	
152	  const handleKeyDown = (event: React.KeyboardEvent) => {
153	    if (event.key === 'Tab' && event.shiftKey && isAccountMenuOpen) {
154	      event.preventDefault();
155	      popoverTriggerRef.current?.focus();
156	    }
157	  };
158	
159	  const handleSignout = async () => {
160	    if (isSigningOut) return;
161	    setIsSigningOut(true);
162	    try {
163	      await onSignout();
164	    } finally {
165	      setIsSigningOut(false);
166	    }
167	  };
168	
169	  return (
170	    <>
171	      {/* ── Tablet + Desktop right: icon buttons at md+, search input at xl+ ─────── */}
172	      {/* chakra.div used intentionally: Flex from shared/ui doesn't reliably apply __css (footer pattern). */}
173	      {/* gap only has visual effect at xl when both searchWrapper and iconGroup are visible. */}
174	      <chakra.div __css={styles.section}>
175	        {menuExpanded === 'fullSwap' ? (
176	          // Desktop/tablet "fullSwap" — a mega menu or drawer is open, so the entire
177	          // search+icon cluster below is replaced by a single Close control. Visible text
178	          // ("Close") already supplies the accessible name — no separate aria-label needed
179	          // on the Button itself (unlike an IconButton, which has no visible text).
180	          <Button variant="unstyled" onClick={onClose} __css={styles.closeControl}>
181	            <Text as="span" textStyle="navigation">
182	              {t('header.button.assistive_msg.close_menu', 'Close')}
183	            </Text>
184	            <ZimmIcon type="close" size="md" aria-hidden={true} />
185	          </Button>
186	        ) : (
187	          <>
188	            {/* Search input — desktop (xl+) only. Figma node 40000259:10795: 180px wide.
189	                ZimmSearchInput is the visual atom wired with SFCC search hooks (useNavigation,
190	                searchUrlBuilder, session recent-search history). Suggestions (useSearchSuggestions
191	                popover) are Sprint 3 work — Squad B scope. At tablet (md), a search icon appears
192	                in tabletSearch instead (Figma node 40000259:13480). */}
193	            <chakra.div __css={styles.searchWrapper}>
194	              <ZimmSearchInput inputRef={searchInputRef} />
195	            </chakra.div>
196	
197	            {/* Icons group — Figma node 40000259:10802 (desktop) / 40000307:11794 (tablet).
198	                Gap: 16px at tablet (--zimm-scale-m), 0 at desktop (var is in rightBar.css.ts recipe). */}
199	            {/* chakra.div used intentionally: Box/Flex from shared/ui don't reliably apply __css — use chakra factory directly (footer pattern). */}
200	            <chakra.div __css={styles.iconGroup}>
201	              {/* Tablet-only search icon (md to xl-1) — desktop shows ZimmSearchInput wrapper above.
202	              chakra.div wrapper controls display reliably; avoids variant="unstyled" specificity race.
203	              Figma node 40000307:11794: search is leftmost in the 4-icon group at tablet. */}
204	              <chakra.div __css={styles.tabletSearch}>
205	                <IconButton
206	                  aria-label={t('header.button.assistive_msg.search', 'Search')}
207	                  icon={<ZimmIcon type="search" size="lg" aria-hidden={true} />}
208	                  variant="unstyled"
209	                  width="var(--zimm-scale-600)"
210	                  height="var(--zimm-scale-600)"
211	                  display="flex"
212	                  alignItems="center"
213	                  justifyContent="center"
214	                  minWidth="unset"
215	                />
216	              </chakra.div>
217	              {/* Commerce agent button — shown only when config enableAgentFromHeader is 'true'. */}
218	              {showLaunchAgentButton && (
219	                <IconButton
220	                  icon={<SparkleIcon />}
221	                  aria-label={t('header.button.assistive_msg.ask_shopping_agent', 'Ask Shopping Agent')}
222	                  variant="unstyled"
223	                  {...headerStyles.icons}
224	                  {...headerStyles.agentIcon}
225	                  onClick={onAgentClick}
226	                />
227	              )}
228	
229	              {/* Profile (Account) icon — Popover for registered users, login-redirect for guests. */}
230	              {/* Touch target: 24px (tablet/md) → 44px (desktop/xl) per Figma nodes 40000307:11794 / 40000259:10802. */}
231	              {/* Icon visual: 24px per Figma node 40002081:16697; ZimmIconSize has no 24px entry (lg=20px) — pending ui-designer sign-off on sizes.ts (Tier 1). */}
232	              {isRegistered && isHydrated() ? (
233	                <Popover
234	                  isLazy
235	                  arrowSize={15}
236	                  isOpen={isAccountMenuOpen}
237	                  placement="bottom-end"
238	                  onClose={onAccountMenuClose}
239	                  onOpen={onAccountMenuOpen}
240	                >
241	                  <PopoverTrigger>
242	                    <IconButton
243	                      aria-label={t('header.button.assistive_msg.my_account', 'My Account')}
244	                      icon={<ZimmIcon type="profile" size="lg" aria-hidden={true} />}
245	                      variant="unstyled"
246	                      width={{ md: 'var(--zimm-scale-600)', xl: 'var(--zimm-scale-1100)' }}
247	                      height={{ md: 'var(--zimm-scale-600)', xl: 'var(--zimm-scale-1100)' }}
248	                      minWidth="unset"
249	                      display="flex"
250	                      justifyContent="center"
251	                      alignItems="center"
252	                      // audit-allow: 999px is the CSS pill-shape idiom for border-radius; no zimm border-radius token exists.
253	                      borderRadius="999px"
254	                      overflow="clip"
255	                      {...getAccountMenuButtonProps()}
256	                      onMouseOver={onAccountMenuOpen}
257	                      onMouseLeave={handleIconsMouseLeave}
258	                      ref={popoverTriggerRef}
259	                      onKeyDown={handleKeyDown}
260	                    />
261	                  </PopoverTrigger>
262	
263	                  <PopoverContent
264	                    {...headerStyles.popoverContent}
265	                    onMouseLeave={() => {
266	                      hasEnterPopoverContent.current = false;
267	                      onAccountMenuClose();
268	                    }}
269	                    onMouseOver={() => {
270	                      hasEnterPopoverContent.current = true;
271	                    }}
