283	                          {filteredNavLinks.map((link) => {
284	                            const LinkIcon = link.icon;
285	                            const label = ACCOUNT_NAV_LABELS[link.name];
286	                            return (
287	                              <chakra.li key={link.name} __css={styles.popoverNavItem}>
288	                                <Button
289	                                  as={Link}
290	                                  to={`/account${link.path}`}
291	                                  useNavLink={true}
292	                                  variant="menu-link"
293	                                  leftIcon={<LinkIcon boxSize={5} />}
294	                                  width="100%"
295	                                >
296	                                  {label ? t(label.key, label.fallback) : link.name}
297	                                </Button>
298	                              </chakra.li>
299	                            );
300	                          })}
301	                        </chakra.ul>
302	                      </chakra.nav>
303	                    </PopoverBody>
304	                    <PopoverFooter onClick={handleSignout} cursor={isSigningOut ? 'not-allowed' : 'pointer'}>
305	                      <Divider colorScheme="gray" />
306	                      <Button variant="unstyled" {...headerStyles.signout} isDisabled={isSigningOut}>
307	                        <chakra.div __css={styles.signoutRow}>
308	                          <SignoutIcon aria-hidden={true} boxSize={5} {...headerStyles.signoutIcon} />
309	                          <Text as="span" {...headerStyles.signoutText}>
310	                            {t('header.popover.action.log_out', 'Log out')}
311	                          </Text>
312	                        </chakra.div>
313	                      </Button>
314	                    </PopoverFooter>
315	                  </PopoverContent>
316	                </Popover>
317	              ) : (
318	                // audit-allow: 999px is the CSS pill-shape idiom for border-radius; no zimm border-radius token exists.
319	                <IconButtonWithRegistration
320	                  aria-label={t('header.button.assistive_msg.my_account', 'My Account')}
321	                  icon={<ZimmIcon type="profile" size="lg" aria-hidden={true} />}
322	                  variant="unstyled"
323	                  width={{ md: 'var(--zimm-scale-600)', xl: 'var(--zimm-scale-1100)' }}
324	                  height={{ md: 'var(--zimm-scale-600)', xl: 'var(--zimm-scale-1100)' }}
325	                  minWidth="unset"
326	                  display="flex"
327	                  justifyContent="center"
328	                  alignItems="center"
329	                  borderRadius="999px"
330	                  overflow="clip"
331	                  onClick={onMyAccountClick}
332	                  onMouseOver={onAccountMenuOpen}
333	                />
334	              )}
335	
336	              {/* Wishlist icon — audit-allow: 999px is the CSS pill-shape idiom for border-radius; no zimm border-radius token exists. */}
337	              <IconButtonWithRegistration
338	                aria-label={t('header.button.assistive_msg.wishlist', 'Wishlist')}
339	                icon={<ZimmIcon type="wishlist" size="lg" aria-hidden={true} />}
340	                variant="unstyled"
341	                width={{ md: 'var(--zimm-scale-600)', xl: 'var(--zimm-scale-1100)' }}
342	                height={{ md: 'var(--zimm-scale-600)', xl: 'var(--zimm-scale-1100)' }}
343	                minWidth="unset"
344	                display="flex"
345	                justifyContent="center"
346	                alignItems="center"
347	                borderRadius="999px"
348	                overflow="clip"
349	                onClick={onWishlistClick}
350	              />
351	
352	              {/* Bag icon — audit-allow: 999px is the CSS pill-shape idiom for border-radius; no zimm border-radius token exists. */}
353	              <IconButton
354	                aria-label={t(
355	                  'header.button.assistive_msg.my_cart_with_num_items',
356	                  'My cart, number of items: {numItems}',
357	                  {
358	                    numItems: totalItems,
359	                  },
360	                )}
361	                icon={
362	                  <>
363	                    <ZimmIcon type="bag" size="lg" aria-hidden={true} />
364	                    {hasBasket && totalItems > 0 && <Badge variant="notification">{totalItems}</Badge>}
365	                  </>
366	                }
367	                variant="unstyled"
368	                width={{ md: 'var(--zimm-scale-600)', xl: 'var(--zimm-scale-1100)' }}
369	                height={{ md: 'var(--zimm-scale-600)', xl: 'var(--zimm-scale-1100)' }}
370	                minWidth="unset"
371	                display="flex"
372	                justifyContent="center"
373	                alignItems="center"
374	                borderRadius="999px"
375	                overflow="clip"
376	                onClick={onMyCartClick}
377	              />
378	            </chakra.div>
379	          </>
380	        )}
381	      </chakra.div>
382	
383	      {/* ── Mobile right: search + store locator + bag (hidden at tablet+) ─────────── */}
384	      {/* chakra.div used intentionally: Flex from shared/ui doesn't reliably apply __css (footer pattern). */}
385	      {/* Figma node 40000259:13476: 24×24px button containers, 20px icon visual, 16px gap (--zimm-scale-m). */}
386	      <chakra.div __css={styles.mobileSection}>
387	        <IconButton
388	          aria-label={t('header.button.assistive_msg.search', 'Search')}
389	          icon={<ZimmIcon type="search" size="lg" aria-hidden={true} />}
390	          variant="unstyled"
391	          width="var(--zimm-scale-600)"
392	          height="var(--zimm-scale-600)"
393	          display="flex"
394	          alignItems="center"
395	          justifyContent="center"
396	          minWidth="unset"
397	        />
398	        {/* Base SFCC account/wishlist icon buttons — disabled at copy-first, superseded by the
399	            Account | Saved | Bag text buttons in the desktop-right block above. HPC-018 requires
400	            Search / Account / Bag in the header; Account ships as text at `lg`+ via that block.
401	            Below `lg` it is absent from the header and only reachable via the burger drawer —
402	            an open HPC-018 question, not a resolved one.
403	            Kept per AGENTS.md's rule on commented-out code. */}
404	        {/* <IconButtonWithRegistration
405	          icon={<AccountIcon />}
406	          aria-label={intl.formatMessage({
407	            id: 'header.button.assistive_msg.my_account',
408	            defaultMessage: 'My Account',
409	          })}
410	          variant="unstyled"
411	          {...headerStyles.icons}
412	          {...headerStyles.accountIcon}
413	          onClick={onMyAccountClick}
414	        />
415	        <IconButtonWithRegistration
416	          aria-label={intl.formatMessage({
417	            defaultMessage: 'Wishlist',
418	            id: 'header.button.assistive_msg.wishlist',
419	          })}
420	          icon={<HeartIcon />}
421	          variant="unstyled"
422	          {...headerStyles.icons}
423	          {...headerStyles.wishlistIcon}
424	          onClick={onWishlistClick}
425	        /> */}
426	        {/* Store locator omitted from mobile — Figma node 40000307:11868 shows only search + bag. */}
427	        <IconButton
428	          aria-label={t('header.button.assistive_msg.my_cart_with_num_items', 'My cart, number of items: {numItems}', {
429	            numItems: totalItems,
430	          })}
431	          icon={
432	            <>
433	              <ZimmIcon type="bag" size="lg" aria-hidden={true} />
434	              {hasBasket && totalItems > 0 && <Badge variant="notification">{totalItems}</Badge>}
435	            </>
436	          }
437	          variant="unstyled"
438	          width="var(--zimm-scale-600)"
439	          height="var(--zimm-scale-600)"
440	          display="flex"
441	          alignItems="center"
442	          justifyContent="center"
443	          minWidth="unset"
444	          onClick={onMyCartClick}
445	        />
446	
447	        {/* mobileL2 only — search + bag stay visible (unlike desktop/tablet's full swap),
448	            plus an added close X. 16px gap (--zimm-scale-m, confirmed Figma node
449	            40002355:40102) applies to all three icons via mobileSection's existing gap —
450	            no separate style needed for this one. No account/wishlist icons at this depth. */}
451	        {menuExpanded === 'mobileL2' && (
452	          <IconButton
453	            aria-label={t('header.button.assistive_msg.close_menu', 'Close')}
454	            icon={<ZimmIcon type="close" size="lg" aria-hidden={true} />}
