import React, { useRef, useState } from 'react';
import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
import {
  IconButton,
  Badge,
  Button,
  Popover,
  PopoverHeader,
  PopoverTrigger,
  PopoverContent,
  PopoverBody,
  PopoverFooter,
  PopoverArrow,
  Text,
  Divider,
  useDisclosure,
} from '@salesforce/retail-react-app/app/components/shared/ui';
import withRegistration from '@salesforce/retail-react-app/app/components/with-registration';
import Link from '@salesforce/retail-react-app/app/components/link';
import { isHydrated, noop } from '@salesforce/retail-react-app/app/utils/utils';
import { SignoutIcon, SparkleIcon } from 'app/components/icons';
import { ZimmIcon } from 'app/components/ui-kits/atoms/zimmIcon';
import { ZimmSearchInput } from 'app/components/ui-kits/atoms/zimmSearchInput';
import { useUiCopy } from 'app/hooks/useUiCopy';
import type { MenuExpandedState } from '../headerTypes';

// `withRegistration` wraps a button so it redirects to login when the user is not
// registered. Kept local to RightBar — only the right section uses it.
const IconButtonWithRegistration = withRegistration(IconButton);

type NavLink = {
  name: string;
  path: string;
  icon: React.ComponentType<{ boxSize: number }>;
};

// The account popover's nav-link labels used to come from base SFCC's own `messages` map
// (@salesforce/retail-react-app/app/pages/account/constant), read via
// `intl.formatMessage(messages[link.name])`. That's vendor react-intl content we don't own,
// with no local uiCopy equivalent — replaced with our own key/fallback pair per `link.name`,
// fallback text matching the vendor map's own defaultMessage so behaviour is unchanged until
// someone edits these in Contentful. `filteredNavLinks` is always sourced from that same
// vendor `navLinks` list (see header/index.tsx), so every real `name` it can contain has an
// entry here — `link.name` itself is the fallback for a name this map doesn't recognise.
const ACCOUNT_NAV_LABELS: Record<string, { key: string; fallback: string }> = {
  profile: { key: 'header.popover.nav.profile', fallback: 'Account Details' },
  addresses: { key: 'header.popover.nav.addresses', fallback: 'Addresses' },
  orders: { key: 'header.popover.nav.orders', fallback: 'Order History' },
  wishlist: { key: 'header.popover.nav.wishlist', fallback: 'Wishlist' },
  payments: { key: 'header.popover.nav.payments', fallback: 'Payment Methods' },
};

type RightBarProps = {
  /** True when an active basket exists — controls bag badge visibility. */
  hasBasket: boolean;
  /** Total item count shown on the bag icon badge. */
  totalItems: number;
  /** Whether the shopper is a registered (logged-in) customer. */
  isRegistered: boolean;
  /** Account nav links, pre-filtered by the shell based on 1CC configuration. */
  filteredNavLinks: ReadonlyArray<NavLink>;
  /** Whether the commerce agent button should be shown (config-driven). */
  showLaunchAgentButton: boolean;
  /** Whether the store locator mobile icon should be shown (config-driven). */
  storeLocatorEnabled: boolean;
  /** Forwarded to ZimmSearchInput for programmatic search focus. */
  searchInputRef?: React.Ref<HTMLInputElement>;
  onMyAccountClick?: () => void;
  onMyCartClick?: () => void;
  onWishlistClick?: () => void;
  onAgentClick?: () => void;
  onStoreLocatorClick?: () => void;
  /** Async logout + navigate handler owned by the header shell container. */
  onSignout: () => Promise<void>;
  /** Current menu-expansion state — see header/headerTypes.ts. Defaults to 'closed'.
   * 'fullSwap' (desktop/tablet) replaces the entire search+icon cluster with a single
   * Close control; 'mobileL2' adds a close icon alongside the mobile search+bag icons.
   * 'mobileL1' has no effect here — that toggle lives entirely in LeftBar's hamburger⇄X.
   * Not wired to any real mega-menu/drawer state on this branch — see headerTypes.ts's
   * scope note (SFCC-96/97 follow-up). */
  menuExpanded?: MenuExpandedState;
  /** Close-control click handler — fires from the desktop/tablet 'fullSwap' control and
   * the mobile 'mobileL2' close icon. Not yet wired to anything real on this branch. */
  onClose?: () => void;
};

/**
 * Header right section — desktop: search input + Profile / Wishlist / Bag icon buttons;
 * tablet: search icon + Profile / Wishlist / Bag icon buttons;
 * mobile: search icon + bag icon only (Figma node 40000307:11868).
 *
 * `menuExpanded` (see header/headerTypes.ts) swaps this section's contents:
 *   - 'closed'/'mobileL1' → unchanged, as above
 *   - 'fullSwap' (desktop/tablet) → the entire search+icon cluster is replaced by a
 *     single "Close" text + X control
 *   - 'mobileL2' → the mobile search + bag icons stay, plus an added close X icon
 *
 * Owns account-popover UI state (useDisclosure, focus refs) internally. Commerce data and
 * auth side-effects are passed as props from the header shell container so this component
 * stays presentational relative to the Commerce Cloud API.
 *
 * Single-parent internal component (only the header shell renders it); story coverage is
 * via the header's own assembly story.
 *
 * @param props see RightBarProps
 */
export const RightBar = ({
  hasBasket,
  totalItems,
  isRegistered,
  filteredNavLinks,
  showLaunchAgentButton,
  storeLocatorEnabled,
  searchInputRef,
  onMyAccountClick = noop,
  onMyCartClick = noop,
  onWishlistClick = noop,
  onAgentClick = noop,
  onStoreLocatorClick = noop,
  onSignout,
  menuExpanded = 'closed',
  onClose = noop,
}: RightBarProps) => {
  const { t } = useUiCopy();
  // Own recipe handles searchWrapper and iconGroup styles.
  const styles = useMultiStyleConfig('ZimmHeaderRightBar');
  // Header theme styles shared with this section: icons, agentIcon, signout*, popoverContent.
  // Referencing the parent Header theme is intentional — these styles live in the SFCC base
  // theme and our header.ts override; duplicating them into ZimmHeaderRightBar would drift.
  const headerStyles = useMultiStyleConfig('Header');

  // Account popover UI state — owned here so the header shell stays free of popover refs.
  const popoverTriggerRef = useRef<HTMLButtonElement>(null);
  const hasEnterPopoverContent = useRef<boolean>();
  const [isSigningOut, setIsSigningOut] = useState(false);

  const {
    getButtonProps: getAccountMenuButtonProps,
    getDisclosureProps: getAccountMenuDisclosureProps,
    isOpen: isAccountMenuOpen,
    onClose: onAccountMenuClose,
    onOpen: onAccountMenuOpen,
  } = useDisclosure();

  const handleIconsMouseLeave = () => {
    // Close menu only if the pointer hasn't moved into the popover content.
    setTimeout(() => {
      if (!hasEnterPopoverContent.current) onAccountMenuClose();
    }, 100);
  };

  const handleKeyDown = (event: React.KeyboardEvent) => {
    if (event.key === 'Tab' && event.shiftKey && isAccountMenuOpen) {
      event.preventDefault();
      popoverTriggerRef.current?.focus();
    }
  };

  const handleSignout = async () => {
    if (isSigningOut) return;
    setIsSigningOut(true);
    try {
      await onSignout();
    } finally {
      setIsSigningOut(false);
    }
  };

  return (
    <>
      {/* ── Tablet + Desktop right: icon buttons at md+, search input at xl+ ─────── */}
      {/* chakra.div used intentionally: Flex from shared/ui doesn't reliably apply __css (footer pattern). */}
      {/* gap only has visual effect at xl when both searchWrapper and iconGroup are visible. */}
      <chakra.div __css={styles.section}>
        {menuExpanded === 'fullSwap' ? (
          // Desktop/tablet "fullSwap" — a mega menu or drawer is open, so the entire
          // search+icon cluster below is replaced by a single Close control. Visible text
          // ("Close") already supplies the accessible name — no separate aria-label needed
          // on the Button itself (unlike an IconButton, which has no visible text).
          <Button variant="unstyled" onClick={onClose} __css={styles.closeControl}>
            <Text as="span" textStyle="navigation">
              {t('header.button.assistive_msg.close_menu', 'Close')}
            </Text>
            <ZimmIcon type="close" size="md" aria-hidden={true} />
          </Button>
        ) : (
          <>
            {/* Search input — desktop (xl+) only. Figma node 40000259:10795: 180px wide.
                ZimmSearchInput is the visual atom wired with SFCC search hooks (useNavigation,
                searchUrlBuilder, session recent-search history). Suggestions (useSearchSuggestions
                popover) are Sprint 3 work — Squad B scope. At tablet (md), a search icon appears
                in tabletSearch instead (Figma node 40000259:13480). */}
            <chakra.div __css={styles.searchWrapper}>
              <ZimmSearchInput inputRef={searchInputRef} />
            </chakra.div>

            {/* Icons group — Figma node 40000259:10802 (desktop) / 40000307:11794 (tablet).
                Gap: 16px at tablet (--zimm-scale-m), 0 at desktop (var is in rightBar.css.ts recipe). */}
            {/* chakra.div used intentionally: Box/Flex from shared/ui don't reliably apply __css — use chakra factory directly (footer pattern). */}
            <chakra.div __css={styles.iconGroup}>
              {/* Tablet-only search icon (md to xl-1) — desktop shows ZimmSearchInput wrapper above.
              chakra.div wrapper controls display reliably; avoids variant="unstyled" specificity race.
              Figma node 40000307:11794: search is leftmost in the 4-icon group at tablet. */}
              <chakra.div __css={styles.tabletSearch}>
                <IconButton
                  aria-label={t('header.button.assistive_msg.search', 'Search')}
                  icon={<ZimmIcon type="search" size="lg" aria-hidden={true} />}
                  variant="unstyled"
                  width="var(--zimm-scale-600)"
                  height="var(--zimm-scale-600)"
                  display="flex"
                  alignItems="center"
                  justifyContent="center"
                  minWidth="unset"
                />
              </chakra.div>
              {/* Commerce agent button — shown only when config enableAgentFromHeader is 'true'. */}
              {showLaunchAgentButton && (
                <IconButton
                  icon={<SparkleIcon />}
                  aria-label={t('header.button.assistive_msg.ask_shopping_agent', 'Ask Shopping Agent')}
                  variant="unstyled"
                  {...headerStyles.icons}
                  {...headerStyles.agentIcon}
                  onClick={onAgentClick}
                />
              )}

              {/* Profile (Account) icon — Popover for registered users, login-redirect for guests. */}
              {/* Touch target: 24px (tablet/md) → 44px (desktop/xl) per Figma nodes 40000307:11794 / 40000259:10802. */}
              {/* Icon visual: 24px per Figma node 40002081:16697; ZimmIconSize has no 24px entry (lg=20px) — pending ui-designer sign-off on sizes.ts (Tier 1). */}
              {isRegistered && isHydrated() ? (
                <Popover
                  isLazy
                  arrowSize={15}
                  isOpen={isAccountMenuOpen}
                  placement="bottom-end"
                  onClose={onAccountMenuClose}
                  onOpen={onAccountMenuOpen}
                >
                  <PopoverTrigger>
                    <IconButton
                      aria-label={t('header.button.assistive_msg.my_account', 'My Account')}
                      icon={<ZimmIcon type="profile" size="lg" aria-hidden={true} />}
                      variant="unstyled"
                      width={{ md: 'var(--zimm-scale-600)', xl: 'var(--zimm-scale-1100)' }}
                      height={{ md: 'var(--zimm-scale-600)', xl: 'var(--zimm-scale-1100)' }}
                      minWidth="unset"
                      display="flex"
                      justifyContent="center"
                      alignItems="center"
                      // audit-allow: 999px is the CSS pill-shape idiom for border-radius; no zimm border-radius token exists.
                      borderRadius="999px"
                      overflow="clip"
                      {...getAccountMenuButtonProps()}
                      onMouseOver={onAccountMenuOpen}
                      onMouseLeave={handleIconsMouseLeave}
                      ref={popoverTriggerRef}
                      onKeyDown={handleKeyDown}
                    />
                  </PopoverTrigger>

                  <PopoverContent
                    {...headerStyles.popoverContent}
                    onMouseLeave={() => {
                      hasEnterPopoverContent.current = false;
                      onAccountMenuClose();
                    }}
                    onMouseOver={() => {
                      hasEnterPopoverContent.current = true;
                    }}
                    {...getAccountMenuDisclosureProps()}
                  >
                    <PopoverArrow />
                    <PopoverHeader>
                      <Text as="h2" fontSize="l" fontFamily="body" fontWeight="700">
                        {t('header.popover.title.my_account', 'My Account')}
                      </Text>
                    </PopoverHeader>
                    <PopoverBody>
                      <chakra.nav>
                        <chakra.ul __css={styles.popoverNavList} data-testid="account-detail-nav">
                          {filteredNavLinks.map((link) => {
                            const LinkIcon = link.icon;
                            const label = ACCOUNT_NAV_LABELS[link.name];
                            return (
                              <chakra.li key={link.name} __css={styles.popoverNavItem}>
                                <Button
                                  as={Link}
                                  to={`/account${link.path}`}
                                  useNavLink={true}
                                  variant="menu-link"
                                  leftIcon={<LinkIcon boxSize={5} />}
                                  width="100%"
                                >
                                  {label ? t(label.key, label.fallback) : link.name}
                                </Button>
                              </chakra.li>
                            );
                          })}
                        </chakra.ul>
                      </chakra.nav>
                    </PopoverBody>
                    <PopoverFooter onClick={handleSignout} cursor={isSigningOut ? 'not-allowed' : 'pointer'}>
                      <Divider colorScheme="gray" />
                      <Button variant="unstyled" {...headerStyles.signout} isDisabled={isSigningOut}>
                        <chakra.div __css={styles.signoutRow}>
                          <SignoutIcon aria-hidden={true} boxSize={5} {...headerStyles.signoutIcon} />
                          <Text as="span" {...headerStyles.signoutText}>
                            {t('header.popover.action.log_out', 'Log out')}
                          </Text>
                        </chakra.div>
                      </Button>
                    </PopoverFooter>
                  </PopoverContent>
                </Popover>
              ) : (
                // audit-allow: 999px is the CSS pill-shape idiom for border-radius; no zimm border-radius token exists.
                <IconButtonWithRegistration
                  aria-label={t('header.button.assistive_msg.my_account', 'My Account')}
                  icon={<ZimmIcon type="profile" size="lg" aria-hidden={true} />}
                  variant="unstyled"
                  width={{ md: 'var(--zimm-scale-600)', xl: 'var(--zimm-scale-1100)' }}
                  height={{ md: 'var(--zimm-scale-600)', xl: 'var(--zimm-scale-1100)' }}
                  minWidth="unset"
                  display="flex"
                  justifyContent="center"
                  alignItems="center"
                  borderRadius="999px"
                  overflow="clip"
                  onClick={onMyAccountClick}
                  onMouseOver={onAccountMenuOpen}
                />
              )}

              {/* Wishlist icon — audit-allow: 999px is the CSS pill-shape idiom for border-radius; no zimm border-radius token exists. */}
              <IconButtonWithRegistration
                aria-label={t('header.button.assistive_msg.wishlist', 'Wishlist')}
                icon={<ZimmIcon type="wishlist" size="lg" aria-hidden={true} />}
                variant="unstyled"
                width={{ md: 'var(--zimm-scale-600)', xl: 'var(--zimm-scale-1100)' }}
                height={{ md: 'var(--zimm-scale-600)', xl: 'var(--zimm-scale-1100)' }}
                minWidth="unset"
                display="flex"
                justifyContent="center"
                alignItems="center"
                borderRadius="999px"
                overflow="clip"
                onClick={onWishlistClick}
              />

              {/* Bag icon — audit-allow: 999px is the CSS pill-shape idiom for border-radius; no zimm border-radius token exists. */}
              <IconButton
                aria-label={t(
                  'header.button.assistive_msg.my_cart_with_num_items',
                  'My cart, number of items: {numItems}',
                  {
                    numItems: totalItems,
                  },
                )}
                icon={
                  <>
                    <ZimmIcon type="bag" size="lg" aria-hidden={true} />
                    {hasBasket && totalItems > 0 && <Badge variant="notification">{totalItems}</Badge>}
                  </>
                }
                variant="unstyled"
                width={{ md: 'var(--zimm-scale-600)', xl: 'var(--zimm-scale-1100)' }}
                height={{ md: 'var(--zimm-scale-600)', xl: 'var(--zimm-scale-1100)' }}
                minWidth="unset"
                display="flex"
                justifyContent="center"
                alignItems="center"
