            Below `lg` it is absent from the header and only reachable via the burger drawer —
            an open HPC-018 question, not a resolved one.
            Kept per AGENTS.md's rule on commented-out code. */}
        {/* <IconButtonWithRegistration
          icon={<AccountIcon />}
          aria-label={intl.formatMessage({
            id: 'header.button.assistive_msg.my_account',
            defaultMessage: 'My Account',
          })}
          variant="unstyled"
          {...headerStyles.icons}
          {...headerStyles.accountIcon}
          onClick={onMyAccountClick}
        />
        <IconButtonWithRegistration
          aria-label={intl.formatMessage({
            defaultMessage: 'Wishlist',
            id: 'header.button.assistive_msg.wishlist',
          })}
          icon={<HeartIcon />}
          variant="unstyled"
          {...headerStyles.icons}
          {...headerStyles.wishlistIcon}
          onClick={onWishlistClick}
        /> */}
        {/* Store locator omitted from mobile — Figma node 40000307:11868 shows only search + bag. */}
        <IconButton
          aria-label={t('header.button.assistive_msg.my_cart_with_num_items', 'My cart, number of items: {numItems}', {
            numItems: totalItems,
          })}
          icon={
            <>
              <ZimmIcon type="bag" size="lg" aria-hidden={true} />
              {hasBasket && totalItems > 0 && <Badge variant="notification">{totalItems}</Badge>}
            </>
          }
          variant="unstyled"
          width="var(--zimm-scale-600)"
          height="var(--zimm-scale-600)"
          display="flex"
          alignItems="center"
          justifyContent="center"
          minWidth="unset"
          onClick={onMyCartClick}
        />

        {/* mobileL2 only — search + bag stay visible (unlike desktop/tablet's full swap),
            plus an added close X. 16px gap (--zimm-scale-m, confirmed Figma node
            40002355:40102) applies to all three icons via mobileSection's existing gap —
            no separate style needed for this one. No account/wishlist icons at this depth. */}
        {menuExpanded === 'mobileL2' && (
          <IconButton
            aria-label={t('header.button.assistive_msg.close_menu', 'Close')}
            icon={<ZimmIcon type="close" size="lg" aria-hidden={true} />}
            variant="unstyled"
            width="var(--zimm-scale-600)"
            height="var(--zimm-scale-600)"
            display="flex"
            alignItems="center"
            justifyContent="center"
            minWidth="unset"
            onClick={onClose}
          />
        )}
      </chakra.div>
    </>
  );
};

