import { BP } from 'app/theme/components/footerShared';
import { breakpoints } from 'app/theme/foundation/gridSystem';

// Provisional spacing/size values — kept here as named references until the UI designer
// confirms the token in foundation/spacing.ts or foundation/sizes.ts.
//
// SPACE_SECTION is NOT a missing token: --zimm-scale-1200 (48px) already carries the same
// value. Kept as rem here because that foundation alias is px, which does not scale under
// browser zoom (WCAG 1.4.4 — see .claude/rules/overrideStyling.md Units). Collapse onto the var
// once the foundation alias moves to rem.
const SPACE_SECTION = '3rem'; // alias/space/section (48px)
const SIZE_COL_SUB = '20rem'; // alias/size/footer/col-width-subscribe (320px)
const SIZE_COL_MAP = '37.5rem'; // alias/size/footer/col-width-sitemap (600px)

// Design direction (2026-09-01): below this width the site-map columns wrap underneath the
// subscribe section instead of sitting beside it — replaces BP.tablet (768px) as the switch
// point for contentRow/subscribe/links/linksInner below, since 768-946px didn't leave enough
// room for both side by side. em, not px, per .claude/rules/overrideStyling.md Units (media
// queries are one of the few genuinely context-relative em uses). No confirmed Figma frame yet.
const BP_CONTENT_WRAP = '59.125em'; // 946px
const COLOUR_HALF_INV = 'rgba(255, 255, 255, 0.5)'; // alias/color/opacity-50-inverse

// footer.css.ts owns only the footer's own shell — root container, main layout, the
// subscribe/links content row, and the logo band. Subscribe content, the subscribe modal, nav
// columns, contact icons, and the bottom bar each own their own recipe now — see
// zimmSubscribeSection.css.ts, zimmSubscribeModal.css.ts, footerNavColumn.css.ts,
// zimmContactIconRow.css.ts, bottomBar.css.ts.
export const ZimmFooter = {
  parts: ['container', 'main', 'contentRow', 'subscribe', 'links', 'linksInner', 'logo', 'logoButton'],
  baseStyle: {
    // ─── Root container ────────────────────────────────────────────────
    container: {
      backgroundColor: 'var(--zimm-color-bg-05)',
      width: '100%',
      maxWidth: 'var(--zimm-grid-max-width)',
      marginLeft: 'auto',
      marginRight: 'auto',
    },

    // ─── Main layout ───────────────────────────────────────────────────
    // Figma: Content area and Logo area are siblings inside the dark footer.
    main: {
      display: 'flex',
      flexDirection: 'column',
    },

    // Figma mobile Content (node 40000407-22493): px-[32px] py-[48px]
    // Figma tablet/desktop Content (node 40000407-23484): pt-[64px] pb-[48px] px-[40px]
    //
    // Horizontal padding is sourced from the shared --zimm-grid-margin-*/--zimm-grid-max-width
    // tokens (gridSystem.ts) — same values apply to header and the main content area, one place
    // to change all three. It steps at gridSystem.ts's `xl` breakpoint (1280px), independent of
    // the layout switch below (flexDirection/justifyContent/gap), which switches at
    // BP_CONTENT_WRAP (946px) — see the const's own comment for why that isn't BP.tablet.
    contentRow: {
      display: 'flex',
      flexDirection: 'column',
      gap: SPACE_SECTION,
      paddingTop: SPACE_SECTION,
      paddingBottom: SPACE_SECTION,
      paddingLeft: 'var(--zimm-grid-margin-mobile)',
      paddingRight: 'var(--zimm-grid-margin-mobile)',
      [`@media (min-width: ${BP_CONTENT_WRAP})`]: {
        flexDirection: 'row',
        justifyContent: 'space-between',
        gap: 0,
        paddingTop: 'var(--zimm-scale-4xl)',
        paddingBottom: SPACE_SECTION,
      },
      [`@media (min-width: ${breakpoints.xl})`]: {
        paddingLeft: 'var(--zimm-grid-margin-desktop)',
        paddingRight: 'var(--zimm-grid-margin-desktop)',
      },
    },

    // Subscribe column — capped at 320px at every breakpoint
    subscribe: {
      maxWidth: SIZE_COL_SUB,
      [`@media (min-width: ${BP_CONTENT_WRAP})`]: {
        flex: `0 0 ${SIZE_COL_SUB}`,
        maxWidth: 'none',
      },
    },

    // Site-map column — fills remaining space once beside subscribe, fixed 600px at desktop
    links: {
      [`@media (min-width: ${BP_CONTENT_WRAP})`]: {
        flex: 1,
      },
      [`@media (min-width: ${BP.desktop})`]: {
        flex: `0 0 ${SIZE_COL_MAP}`,
      },
    },

    // Figma: flex-wrap while stacked under subscribe (2-col), nowrap once beside it, justify-between on desktop
    linksInner: {
      display: 'flex',
      flexWrap: 'wrap',
      gap: 'var(--zimm-scale-3xl)',
      alignContent: 'flex-start',
      alignItems: 'flex-start',
      // Once columns switch from a fixed 140px to content-sized/auto width (footerNavColumn.css.ts,
      // also BP.tablet), they no longer fill the row on their own — space-between spreads them
      // across the full width instead of leaving them bunched at the left. Superseded by the
      // flex-end/space-between values below once the row is no longer stacked under subscribe.
      [`@media (min-width: ${BP.tablet})`]: {
        justifyContent: 'space-between',
      },
      [`@media (min-width: ${BP_CONTENT_WRAP})`]: {
        flexWrap: 'nowrap',
        gap: 'var(--zimm-scale-3xl)',
        justifyContent: 'flex-end',
      },
      [`@media (min-width: ${BP.tabletWide})`]: {
        gap: 'var(--zimm-scale-5xl)',
      },
      [`@media (min-width: ${BP.desktop})`]: {
        gap: 0,
        justifyContent: 'space-between',
      },
    },

    // Figma Logo area: px-[32px] py-[48px] on mobile, px-[40px] at tablet/desktop.
    //
    // The mobile divider above the logo is INSET, not full-bleed. Figma models it as its own
    // Container frame (40000407:23093) holding a Divider vector at x=20 w=362 inside a 402px
    // frame — i.e. 20px clear on each side, bound to alias/space/500 (= spacing.l = 20px). A
    // border-top cannot express that (it always spans the element), so it is drawn as an inset
    // pseudo-element instead. Mobile only: neither the tablet (40000407:23483) nor the desktop
    // (1892:50509) frame contains a Divider node.
    //
    // Colour is still COLOUR_HALF_INV (50% white) pending a visual check — Figma binds
    // alias/color/field/border/inverse/default (#ffffff) on the vector, but the variable list
    // does not expose layer opacity, so an opaque stroke at 50% layer opacity would look
    // identical. See the provisional-token audit (D1-6).
    logo: {
      paddingTop: SPACE_SECTION,
      paddingBottom: SPACE_SECTION,
      paddingLeft: 'var(--zimm-grid-margin-mobile)',
      paddingRight: 'var(--zimm-grid-margin-mobile)',
      display: 'flex',
      flexDirection: 'column',
      justifyContent: 'center',
      alignItems: 'flex-start',
      position: 'relative',
      _before: {
        content: '""',
        position: 'absolute',
        top: 0,
        left: 'var(--zimm-scale-l)',
        right: 'var(--zimm-scale-l)',
        height: 'var(--zimm-border-width-default)',
        background: COLOUR_HALF_INV,
      },
      [`@media (min-width: ${BP.tablet})`]: {
        _before: { display: 'none' },
      },
      [`@media (min-width: ${breakpoints.xl})`]: {
        paddingLeft: 'var(--zimm-grid-margin-desktop)',
        paddingRight: 'var(--zimm-grid-margin-desktop)',
      },
    },
    // Wordmark button — a reset, not a look. The logo owns its own geometry, so this only
    // strips the button chrome and supplies the focus ring the anchor-less markup would
    // otherwise lack (WCAG 2.4.7). Matches the contact icons' ring.
    logoButton: {
      display: 'block',
      background: 'none',
      border: 'none',
      padding: 0,
      cursor: 'pointer',
      _focusVisible: {
        outline: 'var(--zimm-border-width-default) solid',
        outlineColor: 'var(--zimm-color-text-inverse)',
        outlineOffset: 'var(--zimm-focus-ring-offset-default)',
      },
    },
  },
};

