const bodies = document.querySelectorAll('.chakra-popover__body');
const openBody = Array.from(bodies).find(b => getComputedStyle(b).visibility === 'visible');
if (!openBody) { 'NO OPEN BODY FOUND'; } else {
  const links = openBody.querySelectorAll('a');
  const imgs = openBody.querySelectorAll('img');
  const allText = openBody.textContent.trim();
  JSON.stringify({
    innerHTMLLength: openBody.innerHTML.length,
    linkCount: links.length,
    imgCount: imgs.length,
    textContent: allText.slice(0,300),
    firstChildTag: openBody.firstElementChild ? openBody.firstElementChild.tagName : null,
    firstChildHTML: openBody.firstElementChild ? openBody.firstElementChild.outerHTML.slice(0,500) : null
  }, null, 1)
}

const bodies = document.querySelectorAll('.chakra-popover__body');
const openBody = Array.from(bodies).find(b => getComputedStyle(b).visibility === 'visible');
const link = openBody.querySelector('a[href="/clothing/dresses"]');
const chain = [];
let el = link;
for (let i=0; i<7 && el; i++) {
  const cs = getComputedStyle(el);
  chain.push({tag: el.tagName, cls: el.className.toString().slice(0,20), opacity: cs.opacity, visibility: cs.visibility, color: cs.color, transform: cs.transform});
  el = el.parentElement;
}
JSON.stringify(chain, null, 1)

const reveal = document.querySelector('[data-testid="panel-reveal"]');
