  const cs = getComputedStyle(el);
  const r = el.getBoundingClientRect();
  return {testid: el.getAttribute('data-testid'), gridTemplateRows: cs.gridTemplateRows, display: cs.display, height: r.height, width: r.width, overflow: cs.overflow, opacity: cs.opacity};
});
