const dialogs = document.querySelectorAll('[role="dialog"], #drawer-menu-nav, [id*="drawer"]');
JSON.stringify(Array.from(dialogs).map(el => {
  const cs = getComputedStyle(el);
  const r = el.getBoundingClientRect();
  return {id: el.id, ariaLabel: el.getAttribute('aria-label'), display: cs.display, visibility: cs.visibility, transform: cs.transform, height: r.height, width: r.width, opacity: cs.opacity};
}), null, 1)

const btn = document.querySelector('button[aria-label="Menu"]');
JSON.stringify({
  btnExists: !!btn,
  btnAriaExpanded: btn && btn.getAttribute('aria-expanded'),
  bodyOverflow: getComputedStyle(document.body).overflow,
  drawerNav: !!document.getElementById('drawer-menu-nav'),
  allIdsWithDrawer: Array.from(document.querySelectorAll('[id]')).map(e=>e.id).filter(id=>/drawer/i.test(id)),
  allAriaLabelsInBody: Array.from(document.querySelectorAll('[aria-label]')).map(e=>e.getAttribute('aria-label')).filter(l=>/menu|drawer|nav/i.test(l))
}, null, 1)

const headings = Array.from(document.querySelectorAll('footer h3, footer [class*="heading" i], footer p, footer span')).filter(el => ['ABOUT','CONTACT','HELP'].includes(el.textContent.trim()));
JSON.stringify(headings.map(el => {
  const r = el.getBoundingClientRect();
  const cs = getComputedStyle(el.parentElement);
  return {text: el.textContent.trim(), left: r.left, parentPaddingLeft: cs.paddingLeft, parentMarginLeft: cs.marginLeft};
}), null, 1)

const all = Array.from(document.querySelectorAll('footer *')).filter(el => el.children.length === 0 && ['ABOUT','CONTACT','HELP'].includes(el.textContent.trim()));
JSON.stringify(all.map(el => {
  const r = el.getBoundingClientRect();
  const chain = [];
  let p = el;
  for(let i=0;i<4;i++){ p = p.parentElement; if(!p) break; const pr = p.getBoundingClientRect(); const cs = getComputedStyle(p); chain.push({tag:p.tagName, cls: p.className.toString().slice(0,25), left: pr.left, pl: cs.paddingLeft, ml: cs.marginLeft});}
  return {text: el.textContent.trim(), left: r.left, ancestors: chain};
}), null, 1)

const labels = ['ABOUT','CONTACT','HELP'];
const results = {};
document.querySelectorAll('footer *').forEach(el => {
  const t = el.textContent.trim();
  if (labels.includes(t)) {
    const r = el.getBoundingClientRect();
    if (!results[t] || (r.width*r.height) < results[t].area) {
      results[t] = {tag: el.tagName, cls: el.className.toString().slice(0,30), left: r.left, top: r.top, area: r.width*r.height};
    }
  }
});
JSON.stringify(results, null, 1)

const labels = ['about','contact','help'];
const results = {};
document.querySelectorAll('footer *').forEach(el => {
  const t = el.textContent.trim().toLowerCase();
  if (labels.includes(t)) {
    const r = el.getBoundingClientRect();
    if (!results[t] || (r.width*r.height) < results[t].area) {
      results[t] = {tag: el.tagName, cls: el.className.toString().slice(0,30), left: Math.round(r.left*100)/100, top: Math.round(r.top), area: r.width*r.height};
    }
  }
});
JSON.stringify(results, null, 1)

